package kr.or.arte.seal.statistics.web;import kr.or.arte.seal.admin.config.AdminPrincipal;import kr.or.arte.seal.statistics.application.StatisticsQueryService;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.time.*;
@Controller public class StatisticsController {private final StatisticsQueryService service;private final Clock clock;public StatisticsController(StatisticsQueryService s,Clock c){service=s;clock=c;}@GetMapping("/admin/statistics")@PreAuthorize("hasAuthority('STATISTICS_VIEW')")public String index(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to,@AuthenticationPrincipal AdminPrincipal p,Model m){if(to==null)to=LocalDate.now(clock);if(from==null)from=to.minusDays(29);m.addAttribute("administrator",p);m.addAttribute("from",from);m.addAttribute("to",to);m.addAttribute("statistics",service.query(p.adminUserId(),from,to));return "admin/statistics/index";}}
